package de.miraculixx.veinminerEnchant.paper;

import de.miraculixx.veinminer.EnchantmentPack;
import io.papermc.paper.plugin.bootstrap.BootstrapContext;
import io.papermc.paper.plugin.bootstrap.PluginBootstrap;
import io.papermc.paper.plugin.lifecycle.event.types.LifecycleEvents;
import org.jetbrains.annotations.NotNull;

import java.nio.file.Path;

@SuppressWarnings("UnstableApiUsage")
public class VeinminerEnchantmentBootstrapper implements PluginBootstrap {

    @Override
    public void bootstrap(@NotNull BootstrapContext context) {
        // Datapack is generated by Veinminer from plugins/Veinminer/enchantmentSettings.json
        context.getLifecycleManager().registerEventHandler(LifecycleEvents.DATAPACK_DISCOVERY.newHandler(event -> {
            try {
                Path pack = EnchantmentPack.generate(Path.of("plugins", "Veinminer"));
                event.registrar().discoverPack(pack, "enchantment");
            } catch (Exception e) {
                throw new RuntimeException("Failed to load Veinminer enchantment datapack", e);
            }
        }));
    }

}
